  const { pathname, search } = request.nextUrl;

  // Redirect /defaultLocale to root
  if (pathname === `/${defaultLocale}` || pathname.startsWith(`/${defaultLocale}/`)) {
    const url = request.nextUrl.clone();
    url.pathname = pathname.replace(`/${defaultLocale}`, "") || "/";
    return NextResponse.redirect(url, 301);
  }

  // Check for protected route access
  const isProtectedRoute = protectedRoutes.some(route => pathname.startsWith(route));
  const isAuthenticated = Boolean(request.cookies.get("user")?.value);

  if (isProtectedRoute && !isAuthenticated) {
    const redirectPath = (defaultLocale === "en" || !locales.includes(defaultLocale))
      ? "/"
      : `/${defaultLocale}`;
    return NextResponse.redirect(new URL(redirectPath, request.url), 307);
  }

  // Add custom headers
  const customHeaders = new Headers(request.headers);
  customHeaders.set("x-lang-url", defaultLocale);
  customHeaders.set("x-path", pathname);
  customHeaders.set("x-search", search);

  // Pass through i18n middleware
  const i18nResponse = handleI18nRouting(
    new NextRequest(request.nextUrl, { headers: customHeaders })
