Hey 👋 

So right now, Next.js (even in v15) doesn’t have direct support for `React.Activity` inside the App Router. The router tracks navigation/rendering states, but it isn’t connected to React’s activity API yet.

But you can still use it manually. Here’s a small example:

```tsx
'use client';
import { useRouter } from 'next/navigation';
import { useActivity } from 'react';

export default function PageWithActivity() {
  const router = useRouter();
  const activity = useActivity();

  React.useEffect(() => {
    if (!activity.active) {
      // e.g. prefetch next route if user is idle
      router.prefetch('/next');
    }
  }, [activity.active]);

  return <div>{activity.active ? 'Active' : 'Idle'}</div>;
}

How about this implementation? It renders the client initially with some server side user (dummy/build user) and overwrites it client side with the real user afterwards, but keeping the DOM structure. (I also changed SWR to vanilla JS, ignore this).

I tested it and it:
- does not break ISR (no fallback to server rendering)
- successfully overwrites all client side usages like `statsigClient.getFeatureGate('search').value`
- does not rerender the whole DOM

```tsx
'use client'

import type { Statsig } from '@flags-sdk/statsig'
/**
 * This file exports a StatsigProvider with a client-side bootstrap.
 * It requires a client-side fetch to retrieve the bootstrap payload.
 * Elements that determine page layout should have precomputed variants with flags-sdk.
 * Exposures can be logged with helpers in the `statsig-exposure` module.
 */

import { LogLevel, StatsigProvider, useClientBootstrapInit } from '@statsig/react-bindings'
import { createContext, useEffect, useMemo, useRef, useState } from 'react'

export const StatsigAppBootstrapContext = createContext<{
  isLoading: boolean
  error: Error | null
}>({
  isLoading: true,
  error: null,
})

function BootstrappedStatsigProvider({
  user,
  values,
  children,
}: {
  user: Parameters<typeof useClientBootstrapInit>[1]
  values: Parameters<typeof useClientBootstrapInit>[2]
  children: React.ReactNode
}) {
  const initialUser = useRef(user)
  const client = useClientBootstrapInit(process.env.NEXT_PUBLIC_STATSIG_CLIENT_KEY as string, user, values, {
    logLevel: LogLevel.Error,
  })

  useEffect(() => {
    if (initialUser.current === user) return

    async function updateUser() {
      await client?.updateUserAsync(user, {
        priority: 'high',
      })
    }

    updateUser()
  }, [user, client, initialUser])

  return <StatsigProvider client={client}>{children}</StatsigProvider>
}

export function StaticStatsigProvider({ children, initialUser, initialValues }: { children: React.ReactNode, initialUser: any, initialValues: any }) {
  const { data, error } = useBootstrap()
  const values = useMemo(() => JSON.stringify(data), [data])

  if (!data) {
    return (
      <StatsigAppBootstrapContext.Provider value={{ isLoading: true, error }}>
        <BootstrappedStatsigProvider user={initialUser} values={JSON.stringify(initialValues)}>
          {children}
        </BootstrappedStatsigProvider>
      </StatsigAppBootstrapContext.Provider>
    )
  }

  return (
    <StatsigAppBootstrapContext.Provider value={{ isLoading: false, error }}>
      <BootstrappedStatsigProvider user={data.user} values={values}>
        {children}
      </BootstrappedStatsigProvider>
    </StatsigAppBootstrapContext.Provider>
  )
}

export function useBootstrap() {
  const [data, setData] = useState<Awaited<ReturnType<typeof Statsig.getClientInitializeResponse>> | null>(null)
  const [error, setError] = useState<Error | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    let cancelled = false

    async function load() {
      setIsLoading(true)
      try {
        const res = await fetch('/api/bootstrap', {
          headers: {
            Vary: 'Cookie',
          },
        })
        if (!res.ok) {
          throw new Error(`Bootstrap fetch failed: ${res.status}`)
        }
        const json = (await res.json()) as Awaited<ReturnType<typeof Statsig.getClientInitializeResponse>>
        if (!cancelled) {
          setData(json)
        }
      } catch (err: any) {
        if (!cancelled) {
          setError(err)
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    load()
    return () => {
      cancelled = true
    }
  }, [])

  return { data, error, isLoading }
}
```

